CREATE TRIGGER orders_audit
AFTER INSERT ON orders
FOR EACH ROW
EXECUTE FUNCTION audit_orders();

CREATE TRIGGER t_cols
BEFORE UPDATE OF status, user_id ON orders
FOR EACH ROW
EXECUTE FUNCTION audit_cols();

CREATE TRIGGER users_process
AFTER UPDATE ON users
FOR EACH ROW
EXECUTE FUNCTION PROCESS();

CREATE TRIGGER items_stats
AFTER INSERT ON order_items
FOR EACH ROW
EXECUTE FUNCTION REFRESH_STATS();
